jax.tree.reduce / jax.tree_util.tree_reduce uses functools.reduce. Letting n be the number of leaves in the tree, this has a depth / critical path length of O(n). Switching to parallel reduction would bring the critical path length down to O(log n). Example:
import operator

def parallel_reduce(seq, op, identity):
    if len(seq) == 0:
        return identity
    elif len(seq) == 1:
        return seq[0]
    else:
        n = len(seq) // 2
        a = parallel_reduce(seq[:n], op, identity)
        b = parallel_reduce(seq[n:], op, identity)
        return op(a, b)

def parallel_sum(seq):
    return parallel_reduce(seq, operator.add, 0)

def parallel_prod(seq):
    return parallel_reduce(seq, operator.mul, 1)

def parallel_all(seq):
    return parallel_reduce(seq, operator.and_, True)

def parallel_any(seq):
    return parallel_reduce(seq, operator.or_, False)
If this sounds like a good idea, I can submit a PR for it.
